import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture as tslTexture, vec4 } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Create main plane (list row background)
  const planeGeometry = new THREE.PlaneGeometry(6.5, 0.18);

  // Load brushed-metal texture
  const metalTexture = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  metalTexture.colorSpace = THREE.SRGBColorSpace;

  // Create material with TSL texture node
  const material = new MeshBasicNodeMaterial();
  material.colorNode = tslTexture(metalTexture);

  // Create plane mesh
  const planeMesh = new THREE.Mesh(planeGeometry, material);
  planeMesh.position.set(0, 0.7, 0);
  group.add(planeMesh);

  // Add subtle divider line at bottom
  const dividerGeometry = new THREE.PlaneGeometry(6.5, 0.005);
  const dividerMaterial = new MeshBasicNodeMaterial();
  dividerMaterial.colorNode = vec4(0.906, 0.925, 0.949, 0.15); // #e8ecf2 with alpha 0.15

  const divider = new THREE.Mesh(dividerGeometry, dividerMaterial);
  divider.position.set(0, 0.7 - 0.09, 0.001);
  group.add(divider);

  // Store initial state
  const initialPosition = planeMesh.position.clone();
  const initialScale = planeMesh.scale.clone();

  // Create animation timelines
  const hoverTimeline = gsap.timeline({ paused: true });
  const hoverOutTimeline = gsap.timeline({ paused: true });
  const clickTimeline = gsap.timeline();

  // Hover timeline - rise-in effect (0.15 scene units up)
  hoverTimeline.to(planeMesh.position, {
    y: initialPosition.y + 0.15,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);

  // Hover out timeline - return to original position
  hoverOutTimeline.to(planeMesh.position, {
    y: initialPosition.y,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);

  // Event handlers
  const handlers = {
    hover: (isHovering) => {
      if (isHovering) {
        hoverOutTimeline.pause();
        hoverTimeline.restart();
      } else {
        hoverTimeline.pause();
        hoverOutTimeline.restart();
      }
    },
    click: () => {
      // Press-down effect
      clickTimeline.clear();
      clickTimeline
        .to(planeMesh.scale, {
          x: 0.97,
          y: 0.97,
          duration: 0.12,
          ease: 'back.out',
        }, 0)
        .to(planeMesh.scale, {
          x: initialScale.x,
          y: initialScale.y,
          duration: 0.12,
          ease: 'back.out',
        });

      // Emit select event
      if (config.onEvent) {
        config.onEvent('hub-collection.select', { source: 'click' });
      }
    },
  };

  group.userData.handlers = handlers;

  // Cleanup function
  group.userData.cleanup = () => {
    hoverTimeline.kill();
    hoverOutTimeline.kill();
    clickTimeline.kill();
    planeGeometry.dispose();
    material.dispose();
    dividerGeometry.dispose();
    dividerMaterial.dispose();
    metalTexture.dispose();
  };

  return group;
}
